const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
const money=n=>(Number(n||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=v=>v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Ainda não realizado';
const short=v=>String(v||'').slice(0,8);
let state,csrf,route=location.hash.slice(1)||'overview',editorTab='message',welcomeTab='welcome',metadata={channels:[],roles:[],members:[],emojis:[]};
let editor={target:'channel',targetId:'',content:'',webhookName:'',webhookAvatar:'',buttons:[],embed:{title:'Novidades no Studio K ✦',description:'Seu próximo projeto começa aqui.\n\nConheça nossos produtos e converse com a equipe.',color:'#995cff',url:'',author:'Studio K',authorIcon:'',footer:'Feito para a sua comunidade.',image:'',thumbnail:'',timestamp:false,fields:[]}};
let toastTimer;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className=`show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',error?9000:4500);}
async function api(path,method='GET',body,extraHeaders={}){const response=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...extraHeaders},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok){if(response.status===401&&path!=='/login')void boot();throw new Error(data.error||'Não foi possível concluir.');}return data;}
function field(label,name,value='',options={}){const {type='text',help='',placeholder='',required=false,wide=false,min,max,step}=options;return`<div class="field${wide?' wide':''}"><label for="f-${esc(name)}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${esc(name)}" name="${esc(name)}" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step!==undefined?`step="${step}"`:''}>`}${help?`<small>${esc(help)}</small>`:''}</div>`;}
function select(label,name,value,options,help=''){return`<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><select id="f-${esc(name)}" name="${esc(name)}">${options.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function idField(label,name,value,kind='channels'){const items=metadata[kind];return items.length?select(label,name,value,[['','Selecione…'],...items.map(i=>[i.id,kind==='channels'?`# ${i.name}`:i.name])]):field(label,name,value,{placeholder:kind==='roles'?'ID do cargo':'ID do canal',help:'Com o bot conectado, você poderá escolher por nome.'});}
function mentionEmojiTools(prefix='embed'){
  const members=(metadata.members||[]).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).slice(0,500);
  const roles=(metadata.roles||[]).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  const channels=(metadata.channels||[]).filter(c=>c.name).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  const emojis=(metadata.emojis||[]).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  const options=(items,kind)=>items.map(item=>{
    const token=kind==='member'?`<@${item.id}>`:kind==='role'?`<@&${item.id}>`:`<#${item.id}>`;
    const label=kind==='channel'?`# ${item.name}`:kind==='role'?`@${item.name}`:`@${item.name}`;
    return `<option value="${esc(token)}">${esc(label)}</option>`;
  }).join('');
  return `<details class="mention-tools"><summary>Menções avançadas e emojis do servidor</summary>
    <p>Digite IDs manualmente ou selecione abaixo. Pessoa: <code>&lt;@ID&gt;</code> · Cargo: <code>&lt;@&amp;ID&gt;</code> · Canal: <code>&lt;#ID&gt;</code>.</p>
    <div class="mention-insert-grid">
      <label>Pessoa<select data-insert-token><option value="">Selecionar pessoa…</option>${options(members,'member')}</select></label>
      <label>Cargo<select data-insert-token><option value="">Selecionar cargo…</option>${options(roles,'role')}</select></label>
      <label>Canal<select data-insert-token><option value="">Selecionar canal…</option>${options(channels,'channel')}</select></label>
    </div>
    <div class="emoji-picker"><strong>Emojis do servidor</strong>${emojis.length?`<div class="emoji-grid">${emojis.map(e=>{const syntax=`<${e.animated?'a':''}:${e.name}:${e.id}>`;return `<button type="button" class="emoji-insert" data-insert-text="${esc(syntax)}" title=":${esc(e.name)}:"><img src="${esc(e.url)}" alt=":${esc(e.name)}:" loading="lazy"><span>:${esc(e.name)}:</span></button>`;}).join('')}</div>`:'<p class="subtle compact">Nenhum emoji personalizado encontrado neste servidor.</p>'}</div>
  </details>`;
}

const toggle=(label,name,checked)=>`<label class="toggle-label"><input type="checkbox" name="${esc(name)}" ${checked?'checked':''}>${esc(label)}</label>`;
const card=(title,body,extra='',subtitle='')=>`<section class="card"><header class="card-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${extra}</header><div class="card-body">${body}</div></section>`;
const empty=(title,text,action='',name='shop')=>`<div class="empty">${icon(name)}<strong>${esc(title)}</strong><p>${esc(text)}</p>${action}</div>`;
const btn=(text,action,name='',type='')=>`<button class="${type}" data-action="${action}">${name?icon(name):''}${esc(text)}</button>`;
const head=(title,description,actions='')=>`<div class="heading"><div><p class="eyebrow">STUDIO K / CENTRAL DE CONTROLE</p><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;
const statusBadge=s=>{const map={pending:['Aguardando Pix','warn'],paid:['Entrega pendente','purple'],delivered:['Entregue','good'],cancelled:['Cancelado',''],open:['Aberto','purple'],closed:['Encerrado',''],active:['Em andamento','good'],draft:['Publicação pendente','warn'],drawn:['Resultado pendente','warn'],ended:['Encerrado','']};return`<span class="badge ${map[s]?.[1]||''}">${esc(map[s]?.[0]||s)}</span>`;};
const navigation=[['overview','Visão geral','home','PRINCIPAL'],['messages','Mensagens','message'],['welcome','Boas-vindas e saída','users'],['tickets','Tickets','ticket'],['products','Produtos e estoque','shop','COMÉRCIO'],['orders','Pedidos','bag'],['giveaways','Sorteios','gift','COMUNIDADE'],['events','Eventos','calendar'],['verification','Verificação','shield'],['backups','Backups','backup','GERENCIAMENTO'],['logs','Registros','log'],['settings','Configurações','settings']];
function shell(){const title=navigation.find(n=>n[0]===route)?.[1]||'Visão geral';$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><img class="brand-logo" src="https://studio-k-wmrj.netlify.app/logo.png" alt="Studio K"><div>Studio K<small>CONTROL CENTER</small></div></div><div class="server-box"><span class="server-avatar">SK</span><div><strong>${esc(state.status.guild||'Seu servidor')}</strong><small>${state.status.connected?'Conectado ao Discord':'Aguardando conexão'}</small></div></div><nav class="nav">${navigation.map(([key,label,i,group])=>`${group?`<div class="nav-group">${group}</div>`:''}<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(i)}${label}${key==='orders'&&state.summary.pending?`<span class="count">${state.summary.pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-footer"><div class="profile"><span class="server-avatar">K</span><div><strong>Administrador</strong><small>${state.demo?'Ambiente de demonstração':'Acesso ao seu servidor'}</small></div></div></div></aside><main class="main"><header class="topbar"><button class="icon menu-button" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">Seu workspace <span>/ &nbsp;${esc(title)}</span></div><div class="top-actions"><span class="status"><span class="dot ${state.status.connected?'live':''}"></span>${state.demo?'Demonstração':state.status.connected?'Bot conectado':'Bot desconectado'}</span><button class="icon ghost" data-action="refresh" aria-label="Atualizar dados">${icon('refresh')}</button><button class="ghost small" data-action="logout">${icon('logout')}Sair</button></div></header><div class="workspace" id="page"></div></main></div>`;renderPage();}
function renderPage(){const page=$('#page');if(!page)return;const views={overview,messages,welcome,tickets,products,orders,giveaways,events,verification,backups,logs,settings};page.innerHTML=(views[route]||overview)();if(route==='messages')bindPreview();bindEmbedPreviews();}
function overview(){const s=state.settings,openTickets=state.tickets.filter(t=>t.status==='open').length;return`${head('Tudo no seu controle.','Sua loja e sua comunidade, no mesmo lugar.',btn('Criar mensagem','go:messages','plus','primary'))}${state.demo?`<div class="notice">${icon('info')}<span>Você está explorando uma demonstração local. Os produtos são exemplos; nenhuma ação é enviada ao Discord.</span><a href="#settings">Como conectar</a></div>`:!state.status.connected?`<div class="notice warning">${icon('info')}<span>${esc(state.status.error||'Conecte o aplicativo Discord para ativar os envios e as automações.')}</span><a href="#settings">Configurar</a></div>`:''}<div class="stats">${[['Receita confirmada',money(state.summary.revenue),'Apenas pagamentos aprovados','wallet'],['Pedidos',state.summary.orders||0,`${state.summary.pending||0} aguardando conferência`,'bag'],['Tickets abertos',openTickets,'Atendimentos em andamento','ticket'],['Membros',state.status.connected?state.status.members:'—',state.status.connected?'No seu servidor':'Disponível após conectar','users']].map(([label,n,sub,i])=>`<div class="stat"><div class="stat-top">${label}${icon(i)}</div><strong>${n}</strong><small>${sub}</small></div>`).join('')}</div><div class="grid"><div><section class="card welcome-card"><span class="k-watermark">K</span><p class="eyebrow">MENOS TAREFAS. MAIS CRIAÇÃO.</p><h2>Seu próximo projeto começa aqui.</h2><p>Organize produtos, acompanhe cada pedido e mantenha a conversa com seus clientes.</p><button class="small" data-action="go:products">${icon('shop')}Gerenciar catálogo</button></section>${card('Acesso rápido',`<div class="quick-grid">${[['Nova mensagem','Personalize um embed','message','go:messages'],['Novo produto','Dê vida à sua loja','plus','product:new'],['Novo sorteio','Movimente a comunidade','gift','giveaway:new']].map(([a,b,i,c])=>`<button class="quick" data-action="${c}">${icon(i)}<span>${a}</span><small>${b}</small></button>`).join('')}</div>`)}<section class="card"><header class="card-head"><h2>Pedidos recentes</h2><a href="#orders" class="subtle">Ver todos</a></header>${orderTable(state.orders.slice(0,4),false)}</section>${card('Atividade recente',activity(state.logs.slice(0,4)),`<a href="#logs" class="subtle">Ver registros</a>`)}</div><div>${card('Prepare seu Studio K',`<p class="subtle compact">Configure uma vez. Cuide de tudo pelo painel.</p>${[[state.status.connected,'Conecte seu bot','Vincule o Studio K ao seu servidor.','settings'],[!!s.sales.pixKey,'Configure os pagamentos','Defina sua chave Pix e as instruções.','settings'],[state.products.length>0,'Monte seu catálogo','Cadastre produtos digitais e serviços.','products'],[!!s.tickets.staffRoleId,'Organize o atendimento','Escolha a equipe e a categoria dos tickets.','tickets']].map(([done,title,desc,path],i)=>`<div class="check-item"><span class="check-circle ${done?'done':''}">${done?'✓':i+1}</span><div><strong>${title}</strong><p>${desc}</p></div><a href="#${path}" aria-label="${title}">${icon('chevron')}</a></div>`).join('')}`)}${card('Sua operação',`<div class="module-row"><span class="module-icon">${icon('users')}</span><div><strong>Boas-vindas</strong><small>Recepção automática</small></div><span class="badge ${s.welcome.enabled?'good':''}">${s.welcome.enabled?'Ativadas':'Desativadas'}</span></div><div class="module-row"><span class="module-icon">${icon('shield')}</span><div><strong>Verificação</strong><small>Acesso à comunidade</small></div><span class="badge ${s.verification.roleId?'good':''}">${s.verification.roleId?'Configurada':'Configurar'}</span></div><div class="module-row"><span class="module-icon">${icon('backup')}</span><div><strong>Backup automático</strong><small>A cada ${s.backups.intervalHours} horas</small></div><span class="badge ${s.backups.enabled?'good':''}">${s.backups.enabled?'Ativado':'Desativado'}</span></div><p class="subtle">Último backup<br>${date(state.lastBackup)}</p>`)}<p class="footer-note">Studio K · Feito para a sua comunidade.</p></div></div>`;}
function orderTable(items,actions=true){if(!items.length)return empty('Cada venda começa com uma conversa.','Os pedidos aparecerão aqui quando um cliente comprar pelo Discord.',btn('Ver produtos','go:products','shop','small'),'bag');return`<div class="table-wrap"><table><thead><tr><th>Pedido / cliente</th><th>Produto</th><th>Valor</th><th>Situação</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${items.map(o=>`<tr><td><strong>#${short(o.id)}</strong><small>${esc(o.user_id)}</small></td><td><strong>${esc(o.product.name)}</strong><small>${date(o.created)}</small>${o.error?`<p class="inline-error">${esc(o.error)}</p>`:''}</td><td>${money(o.price)}</td><td>${statusBadge(o.status)}</td>${actions?`<td><div class="actions">${o.status==='pending'?btn('Conferir Pix',`approve:${o.id}`,'check','small primary')+btn('Cancelar',`cancel:${o.id}`,'','small ghost'):o.status==='paid'?btn('Tentar entrega',`retry:${o.id}`,'refresh','small'):''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function orders(){const m=state.settings.messageStyles;return`${head('Pedidos','Confira o Pix na sua conta antes de aprovar uma compra.',btn('Criar pedido','order:new','plus','primary'))}${messageStyleCard('Mensagem de entrega ao cliente',m.orderDelivery,'orderDelivery','{product}, {order}, {delivery}, {instructions}')}<div class="notice">${icon('info')}<span>O estoque é reservado até o vencimento. A confirmação libera a entrega e o cargo; serviços seguem para atendimento.</span></div><section class="card">${orderTable(state.orders)}</section>`;}
function activity(items){return items.length?items.map(l=>`<div class="activity"><span class="module-icon">${icon(l.type==='erro'?'info':'log')}</span><div><p>${esc(l.detail)}</p><small>${esc(l.type)} · ${esc(l.actor)}</small></div><span class="activity-time">${date(l.created)}</span></div>`).join(''):empty('Nenhuma atividade ainda.','As ações do bot e do painel serão registradas aqui.','','log');}
function embedForm(e,prefix='embed'){return`<div class="form-grid">${field('Título',`${prefix}.title`,e.title,{wide:true})}${field('Descrição',`${prefix}.description`,e.description,{type:'textarea',wide:true})}${field('Cor',`${prefix}.color`,e.color,{type:'color'})}${field('Link do título',`${prefix}.url`,e.url,{type:'url',placeholder:'https://'})}${field('Autor',`${prefix}.author`,e.author)}${field('Ícone do autor',`${prefix}.authorIcon`,e.authorIcon,{type:'url',placeholder:'https://'})}${field('Imagem grande',`${prefix}.image`,e.image,{type:'url',placeholder:'https://'})}${field('Miniatura',`${prefix}.thumbnail`,e.thumbnail,{type:'url',placeholder:'https://'})}${field('Rodapé',`${prefix}.footer`,e.footer,{wide:true})}</div>${toggle('Mostrar data e hora',`${prefix}.timestamp`,e.timestamp)}${mentionEmojiTools(prefix)}`;}
function embedFieldsForm(e,prefix,path){
  const fields=e.fields||[];
  return `<h3 class="section-label">CAMPOS ADICIONAIS</h3><div>${fields.map((f,i)=>`<div class="field-row">${field('Nome',`${prefix}.fields.${i}.name`,f.name)}${field('Valor',`${prefix}.fields.${i}.value`,f.value)}<div>${toggle('Na mesma linha',`${prefix}.fields.${i}.inline`,f.inline)}<button type="button" class="small ghost" data-action="embedfield:remove:${path}:${i}">${icon('close')}Remover</button></div></div>`).join('')}</div><button type="button" class="small ghost" data-action="embedfield:add:${path}">${icon('plus')}Adicionar campo</button>`;
}
function linkButtonsForm(buttons=[],prefix='buttons',path='buttons'){
  const list=buttons||[];
  return `<h3 class="section-label">BOTÕES DE LINK</h3><div class="link-buttons-editor">${list.map((b,i)=>`<div class="link-button-row">
    ${field('Texto do botão',`${prefix}.${i}.label`,b.label||'',{required:true})}
    ${select('Destino',`${prefix}.${i}.type`,b.type||'url',[['url','Link externo'],['channel','Canal do Discord']])}
    ${field('URL externa',`${prefix}.${i}.url`,b.url||'',{type:'url',placeholder:'https://'})}
    ${idField('Canal',`${prefix}.${i}.channelId`,b.channelId||'')}
    ${field('Emoji (opcional)',`${prefix}.${i}.emoji`,b.emoji||'',{help:'Aceita emoji normal ou emoji personalizado do servidor.'})}
    <div class="link-button-actions"><button type="button" class="small ghost" data-action="linkbutton:remove:${path}:${i}">${icon('close')}Remover</button></div>
  </div>`).join('')}</div><button type="button" class="small ghost" data-action="linkbutton:add:${path}">${icon('plus')}Adicionar botão</button><p class="subtle">Até 5 botões. Para canal, o Studio K gera o link oficial do Discord.</p>`;
}
function styleEditor(style,prefix,variables=''){
  return field('Mensagem acima do embed',`${prefix}.content`,style.content,{type:'textarea',help:'Opcional. Texto enviado antes do embed.'})+
    embedForm(style.embed,`${prefix}.embed`)+embedFieldsForm(style.embed,`${prefix}.embed`,`messageStyles.${prefix}.embed`)+linkButtonsForm(style.buttons||[],`${prefix}.buttons`,`messageStyles.${prefix}.buttons`)+
    (variables?`<div class="notice">${icon('info')}<span>Variáveis disponíveis: ${esc(variables)}</span></div>`:'');
}
function messageStyleCard(title,style,prefix,variables=''){
  const manualPublish=new Set(['ticketPanel','verificationPanel','product','giveaway']).has(prefix);
  return card(title,`<form data-settings="messageStyles" data-preview-style="${esc(prefix)}"><div class="embed-editor-layout"><div class="embed-editor-controls">${styleEditor(style,prefix,variables)}<div class="actions"><button class="primary" type="submit">Salvar personalização</button>${manualPublish?`<button type="button" data-action="embedpublish:messageStyle:${esc(prefix)}">${icon('send')}Publicar este embed</button>`:''}</div></div><aside class="embed-preview-panel"><div class="preview-title"><h3 class="section-label">PRÉ-VISUALIZAÇÃO NO DISCORD</h3><span class="badge purple">AO VIVO</span></div><div class="embed-live-preview" data-preview-target="${esc(prefix)}"></div><p class="subtle">Atualiza em tempo real enquanto você edita. Variáveis usam valores de exemplo.</p></aside></div></form>`);
}

const previewVars={
  user:'@Cliente',username:'cliente',server:'Studio K',count:'1.234',category:'Orçamento',
  ticket:'orcamento-1',staff:'@Atendente',channel:'#orcamento-1',product:'Produto exemplo',
  description:'Descrição do produto',price:'R$ 49,90',availability:'10 unidades',
  title:'Sorteio especial',ends:'em 2 horas',winners:'1',roleLine:'',result:'@Cliente',
  type:'ticket',detail:'Atendimento atualizado.',actor:'@Atendente',order:'ABC123',
  delivery:'CHAVE-EXEMPLO',instructions:'Siga as instruções enviadas.',role:'@Verificado',
  transcript:'https://studio-k-wmrj.netlify.app/transcript'
};
const previewText=value=>String(value||'').replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g,(m,k)=>Object.prototype.hasOwnProperty.call(previewVars,k)?previewVars[k]:m);
function discordRichText(value){
  const text=previewText(value),re=/<(a?):([A-Za-z0-9_]+):(\d+)>|<@!?(\d+)>|<@&(\d+)>|<#(\d+)>/g;
  let out='',last=0,match;
  while((match=re.exec(text))){
    out+=esc(text.slice(last,match.index));
    if(match[3]){
      const emoji=(metadata.emojis||[]).find(e=>e.id===match[3]),animated=match[1]==='a'||emoji?.animated;
      const src=emoji?.url||`https://cdn.discordapp.com/emojis/${match[3]}.${animated?'gif':'png'}?size=48&quality=lossless`;
      out+=`<img class="discord-inline-emoji" src="${esc(src)}" alt=":${esc(match[2])}:" title=":${esc(match[2])}:">`;
    }else if(match[4]){
      const member=(metadata.members||[]).find(m=>m.id===match[4]),label=member?.name||`usuário-${match[4].slice(-4)}`;
      out+=`<span class="discord-mention">@${esc(label)}</span>`;
    }else if(match[5]){
      const role=(metadata.roles||[]).find(r=>r.id===match[5]),label=role?.name||`cargo-${match[5].slice(-4)}`;
      out+=`<span class="discord-mention">@${esc(label)}</span>`;
    }else if(match[6]){
      const channel=(metadata.channels||[]).find(c=>c.id===match[6]),label=channel?.name||`canal-${match[6].slice(-4)}`;
      out+=`<span class="discord-mention">#${esc(label)}</span>`;
    }
    last=re.lastIndex;
  }
  return out+esc(text.slice(last));
}

function discordStylePreview(style,name){
  const e=style?.embed||{},fields=e.fields||[],hasEmbed=!!(e.title||e.description||e.author||e.footer||e.image||e.thumbnail||e.timestamp||fields.length);
  const buttons=(style?.buttons||[]).map(b=>{
    const emoji=b.emoji?discordRichText(b.emoji)+' ':'';
    const channel=(metadata.channels||[]).find(c=>c.id===b.channelId);
    const hint=b.type==='channel'?(channel?`#${channel.name}`:'Canal do Discord'):'Abrir link';
    return `<span class="discord-link-button">${emoji}${esc(b.label||'Botão')} <small>${esc(hint)} ↗</small></span>`;
  }).join('');
  return `<div class="discord-preview"><span class="discord-avatar">K</span><div class="discord-body"><div class="discord-name">${esc(name||state.settings.brand.name)}<span class="app-badge">APP</span><time>Hoje</time></div>${style?.content?`<div class="discord-content">${discordRichText(style.content)}</div>`:''}${hasEmbed?`<div class="embed" style="border-color:${/^#[0-9a-f]{6}$/i.test(e.color||'')?e.color:'#995cff'}">${e.thumbnail&&validImage(e.thumbnail)?`<img class="embed-thumb" src="${validImage(e.thumbnail)}" alt="" referrerpolicy="no-referrer">`:''}${e.author?`<div class="embed-author">${e.authorIcon&&validImage(e.authorIcon)?`<img src="${validImage(e.authorIcon)}" alt="" referrerpolicy="no-referrer">`:''}${discordRichText(e.author)}</div>`:''}${e.title?`<h3>${discordRichText(e.title)}</h3>`:''}${e.description?`<p>${discordRichText(e.description)}</p>`:''}<div class="embed-fields">${fields.map(f=>`<div class="embed-field ${f.inline?'inline':''}"><strong>${discordRichText(f.name)}</strong>${discordRichText(f.value)}</div>`).join('')}</div>${e.image&&validImage(e.image)?`<img class="embed-image" src="${validImage(e.image)}" alt="Imagem do embed" referrerpolicy="no-referrer">`:''}${e.footer||e.timestamp?`<div class="embed-footer">${discordRichText(e.footer)}${e.timestamp?`${e.footer?' · ':''}Hoje`:''}</div>`:''}</div>`:'<div class="subtle" style="margin-top:8px">O embed aparecerá aqui conforme você preencher os campos.</div>'}${buttons?`<div class="discord-link-buttons">${buttons}</div>`:''}</div></div>`;
}
function readStylePreview(form,prefix,base){
  const d=new FormData(form),style=structuredClone(base||{content:'',embed:{fields:[]}}),e=style.embed||(style.embed={fields:[]});
  style.content=d.get(`${prefix}.content`)??style.content??'';
  for(const key of ['title','description','color','url','author','authorIcon','footer','image','thumbnail'])e[key]=d.get(`${prefix}.embed.${key}`)??e[key]??'';
  e.timestamp=d.has(`${prefix}.embed.timestamp`);
  e.fields=(e.fields||[]).map((field,i)=>({
    name:d.get(`${prefix}.embed.fields.${i}.name`)??field.name??'',
    value:d.get(`${prefix}.embed.fields.${i}.value`)??field.value??'',
    inline:d.has(`${prefix}.embed.fields.${i}.inline`)
  }));
  style.buttons=(base.buttons||[]).map((b,i)=>({
    label:d.get(`${prefix}.buttons.${i}.label`)??b.label??'',
    type:d.get(`${prefix}.buttons.${i}.type`)??b.type??'url',
    url:d.get(`${prefix}.buttons.${i}.url`)??b.url??'',
    channelId:d.get(`${prefix}.buttons.${i}.channelId`)??b.channelId??'',
    emoji:d.get(`${prefix}.buttons.${i}.emoji`)??b.emoji??''
  }));
  return style;
}
function readTemplatePreview(form,key,base){
  const d=new FormData(form),style={content:d.get('content')??base.content??'',embed:structuredClone(base.embed||{fields:[]})},e=style.embed;
  for(const field of ['title','description','color','url','author','authorIcon','footer','image','thumbnail'])e[field]=d.get(`embed.${field}`)??e[field]??'';
  e.timestamp=d.has('embed.timestamp');
  e.fields=(e.fields||[]).map((item,i)=>({
    name:d.get(`embed.fields.${i}.name`)??item.name??'',
    value:d.get(`embed.fields.${i}.value`)??item.value??'',
    inline:d.has(`embed.fields.${i}.inline`)
  }));
  style.buttons=(base.buttons||[]).map((b,i)=>({
    label:d.get(`buttons.${i}.label`)??b.label??'',
    type:d.get(`buttons.${i}.type`)??b.type??'url',
    url:d.get(`buttons.${i}.url`)??b.url??'',
    channelId:d.get(`buttons.${i}.channelId`)??b.channelId??'',
    emoji:d.get(`buttons.${i}.emoji`)??b.emoji??''
  }));
  return style;
}
function bindEmbedPreviews(){
  document.querySelectorAll('form[data-preview-style]').forEach(form=>{
    const prefix=form.dataset.previewStyle,target=form.querySelector('[data-preview-target]'),base=state.settings.messageStyles[prefix];
    if(!target||!base)return;
    const render=()=>{target.innerHTML=discordStylePreview(readStylePreview(form,prefix,base));};
    form.addEventListener('input',render);form.addEventListener('change',render);render();
  });
  document.querySelectorAll('form[data-preview-template]').forEach(form=>{
    const key=form.dataset.previewTemplate,target=form.querySelector('[data-template-preview]'),base=state.settings[key];
    if(!target||!base)return;
    const render=()=>{target.innerHTML=discordStylePreview(readTemplatePreview(form,key,base));};
    form.addEventListener('input',render);form.addEventListener('change',render);render();
  });
}
function messages(){return`${head('Mensagens que têm a sua cara.','Crie, visualize e envie mensagens para canais ou membros.')}<div class="grid equal"><div>${card('Editor de mensagens',`<form id="message-form"><div class="form-grid">${select('Destino','target',editor.target,[['channel','Canal do servidor'],['dm','Mensagem privada']])}${field('ID do destinatário','targetId',editor.targetId,{placeholder:editor.target==='dm'?'ID do membro':'ID do canal',required:true})}</div><p class="subtle">No privado, o membro precisa ativar <code>/notificacoes</code>. A identidade será sempre a do Studio K.</p>${field('Mensagem','content',editor.content,{type:'textarea',placeholder:'Escreva uma mensagem antes do embed…'})}<div class="divider"></div><h3 class="section-label">PERSONALIZAÇÃO DO EMBED</h3>${embedForm(editor.embed)}<h3 class="section-label">CAMPOS ADICIONAIS</h3><div id="embed-fields">${editor.embed.fields.map((f,i)=>`<div class="field-row">${field('Nome',`fields.${i}.name`,f.name)}${field('Valor',`fields.${i}.value`,f.value)}<div>${toggle('Na mesma linha',`fields.${i}.inline`,f.inline)}<button type="button" class="small ghost" data-action="field:remove:${i}" aria-label="Excluir campo ${i+1}">${icon('close')}</button></div></div>`).join('')}</div><button type="button" class="small ghost" data-action="field:add">${icon('plus')}Adicionar campo</button>${linkButtonsForm(editor.buttons||[],'buttons','editor.buttons')}<details><summary>Identidade de webhook para canais</summary><p>Opcional. Permite nome e avatar próprios nesta mensagem do canal.</p>${field('Nome de exibição','webhookName',editor.webhookName)}${field('URL do avatar','webhookAvatar',editor.webhookAvatar,{type:'url',placeholder:'https://'})}</details><div class="divider"></div><p class="inline-error" id="message-error"></p><div class="actions"><button class="primary" type="submit">${icon('send')}Revisar envio</button><button type="button" data-action="template:save">Salvar modelo</button></div></form>`)}${state.templates.length?card('Seus modelos',state.templates.map(t=>`<div class="module-row"><strong>${esc(t.name)}</strong><div class="actions" style="margin-left:auto">${btn('Usar',`template:load:${t.id}`,'','small')}${btn('Excluir',`template:delete:${t.id}`,'close','small ghost')}</div></div>`).join('')):''}</div><div class="sticky-preview">${card('Prévia no Discord','<div id="embed-preview"></div><p class="subtle">Prévia aproximada. O Discord pode ajustar espaçamentos e formatação.</p>','<span class="badge purple">AO VIVO</span>')}${card('Pequenos detalhes, grande diferença.',`<p class="subtle compact">Use o título para chamar atenção, a descrição para explicar e os campos para organizar preços, prazos e informações úteis.</p><div class="divider"></div><p class="subtle compact">Limites: título de 256 caracteres, descrição de 4.096, até 25 campos e 6.000 caracteres no total do embed. Menções em massa ficam desativadas.</p>`)}</div></div>`;}
function collectEditor(){const form=$('#message-form');if(!form)return;const d=new FormData(form);const fields=editor.embed.fields.map((_,i)=>({name:d.get(`fields.${i}.name`)||'',value:d.get(`fields.${i}.value`)||'',inline:d.has(`fields.${i}.inline`)}));const buttons=(editor.buttons||[]).map((b,i)=>({label:d.get(`buttons.${i}.label`)||'',type:d.get(`buttons.${i}.type`)||'url',url:d.get(`buttons.${i}.url`)||'',channelId:d.get(`buttons.${i}.channelId`)||'',emoji:d.get(`buttons.${i}.emoji`)||''}));editor={target:d.get('target'),targetId:d.get('targetId'),content:d.get('content'),webhookName:d.get('webhookName'),webhookAvatar:d.get('webhookAvatar'),buttons,embed:{...editor.embed,fields}};for(const key of ['title','description','color','url','author','authorIcon','footer','image','thumbnail'])editor.embed[key]=d.get(`embed.${key}`)||'';editor.embed.timestamp=d.has('embed.timestamp');}
const validImage=url=>/^https:\/\//.test(url)?esc(url):'';
function preview(){return discordStylePreview(editor,editor.target==='channel'&&editor.webhookName?editor.webhookName:state.settings.brand.name);}
function bindPreview(){const render=()=>{collectEditor();$('#embed-preview').innerHTML=preview();};$('#message-form').addEventListener('input',render);render();$('#message-form').addEventListener('submit',e=>{e.preventDefault();collectEditor();confirmAction('Enviar mensagem',`A mensagem será enviada ${editor.target==='dm'?'no privado do membro':'no canal'} ${editor.targetId}.`,async()=>{await api('/messages','POST',editor);toast('Mensagem enviada ao Discord.');await refresh(false);},'Enviar agora');});}
